-- Map legacy Claude Haiku 3.5 requests to the currently supported Haiku 4.5 model.
--
-- Anthropic-compatible API key accounts may keep explicit model_mapping entries
-- generated by older UI presets. Leaving those entries as self-maps sends
-- claude-3-5-haiku-20241022 upstream and now returns 404, surfaced as 502.

WITH changed AS (
  UPDATE accounts
  SET credentials = jsonb_set(
        jsonb_set(
          credentials,
          ARRAY['model_mapping', 'claude-3-5-haiku-20241022'],
          to_jsonb('claude-haiku-4-5-20251001'::text),
          true
        ),
        ARRAY['model_mapping', 'anthropic/claude-3-5-haiku-20241022'],
        to_jsonb('claude-haiku-4-5-20251001'::text),
        true
      ),
      updated_at = NOW()
  WHERE platform = 'anthropic'
    AND deleted_at IS NULL
    AND (
      credentials->'model_mapping'->>'claude-3-5-haiku-20241022' = 'claude-3-5-haiku-20241022'
      OR credentials->'model_mapping'->>'anthropic/claude-3-5-haiku-20241022' = 'claude-3-5-haiku-20241022'
    )
  RETURNING id
)
INSERT INTO scheduler_outbox (event_type, account_id, group_id, payload)
SELECT 'account_changed', id, NULL, NULL
FROM changed;
